UPDATE user_ai_saved_credential SET modifier = #{userId}, key_name = #{keyName}, base_url = #{baseUrl}, api_key = #{apiKey},
    secret_key = #{secretKey}, is_active = #{active}, last_check_status = #{lastCheckStatus}, last_check_time = #{lastCheckTime}
WHERE credential_id = #{credentialId} AND user_id = #{userId} AND del_flag = 0

UPDATE user_ai_saved_credential SET modifier = #{credential.userId}, last_check_status = #{status}, last_check_time = #{time}
WHERE credential_id = #{credential.credentialId} AND user_id = #{credential.userId} AND del_flag = 0
  AND BINARY api_key = BINARY #{credential.apiKey} AND BINARY base_url = BINARY #{credential.baseUrl}
  AND (BINARY secret_key = BINARY #{credential.secretKey} OR (secret_key IS NULL AND #{credential.secretKey} IS NULL))
